.consciouscap-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #243524;
    background: linear-gradient(160deg, #f3f7ec 0%, #e7f0dd 100%);
    border-radius: 18px;
}

.consciouscap-container * {
    box-sizing: border-box;
}

.consciouscap-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #1f5130 0%, #2f7d45 55%, #4ca35f 100%);
    color: #f3faef;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(31, 81, 48, 0.30);
}

.consciouscap-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.consciouscap-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #cdeccf;
    background: rgba(255, 255, 255, 0.13);
    padding: 5px 14px;
    border-radius: 999px;
}

.consciouscap-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #e3f2d9;
}

.consciouscap-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #305b39;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.consciouscap-period-counter #currentDay,
.consciouscap-period-counter #maxPeriods {
    font-weight: 800;
    color: #1f5130;
}

.consciouscap-round-name {
    background: #d4e9c8;
    color: #1f5130;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.consciouscap-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4a1a;
    background: #f7e4cf;
    padding: 4px 12px;
    border-radius: 999px;
}

.consciouscap-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.consciouscap-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d8e6c9;
    box-shadow: 0 4px 14px rgba(31, 81, 48, 0.06);
    border-top: 4px solid #4ca35f;
}

.consciouscap-card-value { border-top-color: #2f7d45; }
.consciouscap-card-trust { border-top-color: #2a7da3; }
.consciouscap-card-credibility { border-top-color: #7a4fb0; }
.consciouscap-card-budget { border-top-color: #c08a16; }

.consciouscap-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #6a7d5e;
}

.consciouscap-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #1f5130;
}

.consciouscap-card-value .consciouscap-value { color: #2f7d45; }
.consciouscap-card-trust .consciouscap-value { color: #2a7da3; }
.consciouscap-card-credibility .consciouscap-value { color: #7a4fb0; }
.consciouscap-card-budget .consciouscap-value { color: #c08a16; }

.consciouscap-sublabel {
    font-size: 0.76rem;
    color: #7d8d72;
    line-height: 1.35;
}

.consciouscap-trust-recovered .consciouscap-value { color: #2f7d45; }
.consciouscap-trust-crisis .consciouscap-value { color: #c0392b; }

.consciouscap-budget-over { border-top-color: #c0392b; }
.consciouscap-budget-over .consciouscap-value { color: #c0392b; }

.consciouscap-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #1f5130;
    color: #eaf6e2;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.consciouscap-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.consciouscap-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #4ca35f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(31, 81, 48, 0.05);
}

.consciouscap-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.consciouscap-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #1f5130;
    margin-bottom: 6px;
}

.consciouscap-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #36482f;
}

.consciouscap-briefing-text strong { color: #2f7d45; }
.consciouscap-briefing-text em { color: #9a4a1a; font-style: italic; }

.consciouscap-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d8e6c9;
    box-shadow: 0 4px 14px rgba(31, 81, 48, 0.06);
}

.consciouscap-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #1f5130;
    border-bottom: 2px solid #e7f0dd;
    padding-bottom: 8px;
}

.consciouscap-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #2c4a2c;
    margin: 14px 0 6px;
}

.consciouscap-container select,
.consciouscap-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #c2d8af;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f8fcf2;
    color: #243524;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.consciouscap-container select:focus,
.consciouscap-container input[type="number"]:focus {
    outline: none;
    border-color: #4ca35f;
    box-shadow: 0 0 0 3px rgba(76, 163, 95, 0.16);
}

.consciouscap-container select option {
    background-color: #ffffff;
    color: #243524;
}

.consciouscap-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #4ca35f;
}

.consciouscap-range-readout,
.consciouscap-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #2f7d45;
    margin-top: 4px;
}

.consciouscap-range-readout span:last-child,
.consciouscap-alloc-readout span:nth-child(2) {
    color: #1f5130;
    font-weight: 800;
}

.consciouscap-hint {
    font-size: 0.8rem;
    color: #7d8d72;
    margin-top: 6px;
    line-height: 1.4;
}

.consciouscap-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.consciouscap-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f3f9eb;
    border: 1px solid #dceace;
    border-radius: 9px;
    padding: 8px 12px;
}

.consciouscap-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #2c4a2c;
}

.consciouscap-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.consciouscap-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.consciouscap-container .btn-primary {
    background: linear-gradient(135deg, #2f7d45 0%, #4ca35f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(47, 125, 69, 0.28);
}

.consciouscap-container .btn-primary:hover {
    filter: brightness(1.06);
}

.consciouscap-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #c2d8af;
    color: #6a7d5e;
}

.consciouscap-coach {
    background: #1f5130;
    color: #eaf6e2;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(31, 81, 48, 0.22);
}

.consciouscap-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #95d49b;
    margin-bottom: 8px;
}

.consciouscap-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.consciouscap-coach-body strong { color: #ffe08a; }
.consciouscap-coach-body em { color: #ffc1ad; font-style: italic; }

.consciouscap-history,
.consciouscap-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d8e6c9;
    box-shadow: 0 4px 14px rgba(31, 81, 48, 0.06);
}

.consciouscap-history h3,
.consciouscap-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #1f5130;
}

.consciouscap-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #2c4a2c;
}

.consciouscap-container table#usfHistoryTable th {
    background: #e9f2dd;
    color: #1f5130;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6c4;
}

.consciouscap-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4e6;
}

.consciouscap-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f8fbf2;
}

.consciouscap-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .consciouscap-container {
        padding: 14px;
    }
    .consciouscap-header h1 {
        font-size: 1.7rem;
    }
    .consciouscap-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .consciouscap-value {
        font-size: 2rem;
    }
    .consciouscap-clock {
        margin-left: 0;
    }
    .consciouscap-period-counter {
        font-size: 0.88rem;
    }
    .consciouscap-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .consciouscap-alloc-row {
        flex-wrap: wrap;
    }
    .consciouscap-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .consciouscap-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (append-only, dark-on-light) ===== */
.consciouscap-completion { color:#25302a; font-size:0.95rem; }
.consciouscap-cm-head { text-align:center; margin-bottom:16px; }
.consciouscap-cm-score { font-size:3.2rem; font-weight:800; line-height:1; color:#4a7a3f; }
.consciouscap-cm-score-max { font-size:1.2rem; font-weight:600; color:#7ba86f; }
.consciouscap-cm-grade { font-size:1.2rem; font-weight:700; margin-top:6px; color:#1c2a1f; }
.consciouscap-cm-badge { display:inline-block; margin-left:6px; padding:2px 10px; border-radius:999px; font-size:0.78rem; font-weight:700; vertical-align:middle; }
.consciouscap-cm-yes { background:rgba(74,122,63,0.14); color:#3c6633; border:1px solid rgba(74,122,63,0.5); }
.consciouscap-cm-no { background:rgba(201,138,22,0.16); color:#8a6a1f; border:1px solid rgba(201,138,22,0.5); }
.consciouscap-cm-fail { background:rgba(192,57,43,0.12); color:#b0392b; border:1px solid rgba(192,57,43,0.45); }
.consciouscap-cm-metrics { display:flex; flex-wrap:wrap; gap:10px; justify-content:center; margin:12px 0 16px; }
.consciouscap-cm-metric { flex:1 1 110px; min-width:100px; background:rgba(28,42,31,0.06); border:1px solid rgba(28,42,31,0.16); border-radius:10px; padding:10px 8px; text-align:center; }
.consciouscap-cm-mv { display:block; font-size:1.4rem; font-weight:800; color:#20372a; }
.consciouscap-cm-ml { display:block; font-size:0.72rem; margin-top:4px; color:#6a7d5e; text-transform:uppercase; letter-spacing:0.03em; }
.consciouscap-cm-insights-title { font-weight:700; margin:8px 0 6px; color:#1c2a1f; }
.consciouscap-cm-insights { margin:0; padding-left:20px; }
.consciouscap-cm-insights li { margin:4px 0; color:#2f4535; }

