(function() {
    'use strict';

    class ConsciousCapAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Conscious Capital`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (R$ millions unless noted).
            this.START_VALUE = 20;        // stakeholder value index, headroom to grow
            this.START_TRUST = 61;        // brand-trust index (fell 72 -> 61)
            this.TRUST_ORIGINAL = 72;     // pre-crisis level to recover toward
            this.START_CREDIBILITY = 15;  // unassured glossy brochure only
            this.BUDGET_CAP = 28;         // R$28M hard sustainability budget
            this.COST_EVERYTHING = 52;    // ~R$52M to fund everything -> forces prioritising

            // Win target for "Conscious Capital" performance.
            this.TARGET_TRUST = 70;       // credible recovery toward the original 72
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    value: this.START_VALUE,
                    trust: this.START_TRUST,
                    credibility: this.START_CREDIBILITY,
                    budgetUsed: 0,
                    greenwashFlag: false,
                    delisted: false,
                    valueHistory: [this.START_VALUE],
                    trustHistory: [this.START_TRUST],
                    credibilityHistory: [this.START_CREDIBILITY],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are deliberately MIDDLING (not the textbook play):
                // farmers+power lens, an even thin R$24M spread, an unassured own-ops brochure,
                // and a lightly-evidenced "confident" claim. A click-through must not auto-win.
                state.decisions = {
                    priority: `farmers`,
                    lens: `power`,
                    alignment: 50,
                    water: 6,
                    sourcing: 6,
                    riders: 6,
                    community: 6,
                    focus: `spread`,
                    framework: `brochure`,
                    assurance: `none`,
                    boundary: `ownops`,
                    disclose: 50,
                    claim: `confident`,
                    coherence: `partial`,
                    followup: `monitor`,
                    restraint: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const pr = document.getElementById(`priorityInput`);
                const ln = document.getElementById(`lensInput`);
                const al = document.getElementById(`alignmentInput`);
                if (pr) decisions.priority = pr.value;
                if (ln) decisions.lens = ln.value;
                if (al) decisions.alignment = parseInt(al.value, 10);
                if (!Number.isFinite(decisions.alignment) || decisions.alignment < 0 || decisions.alignment > 100) {
                    warn(`warn_alignment_range`); return false;
                }
            } else if (round === 2) {
                const ids = [`waterInput`, `sourcingInput`, `ridersInput`, `communityInput`];
                const keys = [`water`, `sourcing`, `riders`, `community`];
                for (let i = 0; i < ids.length; i++) {
                    const el = document.getElementById(ids[i]);
                    if (el) decisions[keys[i]] = parseFloat(el.value);
                }
                const parts = keys.map((k) => decisions[k]);
                if (parts.some((v) => !Number.isFinite(v) || v < 0)) {
                    warn(`warn_alloc_negative`); return false;
                }
                const total = Math.round((decisions.water + decisions.sourcing + decisions.riders + decisions.community) * 10) / 10;
                if (total > this.BUDGET_CAP + 0.001) {
                    warn(`warn_alloc_over`); return false;
                }
                if (total <= 0) {
                    warn(`warn_alloc_zero`); return false;
                }
                const fo = document.getElementById(`focusInput`);
                if (fo) decisions.focus = fo.value;
            } else if (round === 3) {
                const fw = document.getElementById(`frameworkInput`);
                const as = document.getElementById(`assuranceInput`);
                const bd = document.getElementById(`boundaryInput`);
                const di = document.getElementById(`discloseInput`);
                if (fw) decisions.framework = fw.value;
                if (as) decisions.assurance = as.value;
                if (bd) decisions.boundary = bd.value;
                if (di) decisions.disclose = parseInt(di.value, 10);
                if (!Number.isFinite(decisions.disclose) || decisions.disclose < 0 || decisions.disclose > 100) {
                    warn(`warn_disclose_range`); return false;
                }
            } else if (round === 4) {
                const cl = document.getElementById(`claimInput`);
                const co = document.getElementById(`coherenceInput`);
                const fu = document.getElementById(`followupInput`);
                const re = document.getElementById(`restraintInput`);
                if (cl) decisions.claim = cl.value;
                if (co) decisions.coherence = co.value;
                if (fu) decisions.followup = fu.value;
                if (re) decisions.restraint = parseInt(re.value, 10);
                if (!Number.isFinite(decisions.restraint) || decisions.restraint < 0 || decisions.restraint > 100) {
                    warn(`warn_restraint_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // valueDelta = real stakeholder value created; credDelta = verified-disclosure credibility;
            // spinDelta = marketing/PR that lifts trust short-term but is NOT backed by substance;
            // spend = R$M committed this round.
            let valueDelta = 0, credDelta = 0, spinDelta = 0, trustDirect = 0;
            let spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Materiality over salience (Common Error 1). The most material issue (water &
                // sourcing) serves several stakeholders at once; chasing the loudest pressure
                // (retail/consumer PR) leaves the time bomb unfunded.
                switch (d.priority) {
                    case `material`: valueDelta += 11; credDelta += 3; coachKey = `coach_r1_material`; break;
                    case `farmers`:  valueDelta += 6;  credDelta += 1; coachKey = `coach_r1_farmers`; break;
                    case `riders`:   valueDelta += 1;  trustDirect += 1; coachKey = `coach_r1_riders`; break;
                    case `retail`:   valueDelta -= 5;  trustDirect += 3; spinDelta += 4; coachKey = `coach_r1_retail`; break;
                }

                // The lens that decides the priority.
                switch (d.lens) {
                    case `materiality`: valueDelta += 7; credDelta += 3; if (d.priority === `material`) coachKey = `coach_r1_sharp`; break;
                    case `salience`:    valueDelta -= 6; spinDelta += 5; coachKey = (d.priority === `retail`) ? coachKey : `coach_r1_salience`; break;
                    case `power`:       valueDelta -= 4; coachKey = (coachKey === `coach_default`) ? `coach_r1_power` : coachKey; break;
                    case `none`:        valueDelta -= 7; coachKey = `coach_r1_nolens`; break;
                }

                // Looking for an integrated priority that serves several stakeholders (conscious
                // capitalism: align, don't rank by power).
                if (d.alignment >= 70) { valueDelta += 4; }
                else if (d.alignment <= 25) { valueDelta -= 5; }

                summaryKey = (d.priority === `material` && d.lens === `materiality`) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Fund the right CSR portfolio under the R$28M cap (Common Error 2 & budget tree).
                const material = d.water + d.sourcing;   // substantive, high-materiality spend
                const visible = d.riders;                 // visible labour fix, moderate value
                const photogenic = d.community;           // popular, photogenic, low materiality
                spend = material + visible + photogenic;

                // Concentration on material initiatives creates the most stakeholder value.
                // Each material real funds genuine value; the water retrofit specifically lifts
                // credibility because it answers the named effluent risk.
                valueDelta += Math.min(15, material * 0.95);
                if (d.water >= 8) { credDelta += 5; } else if (d.water >= 4) { credDelta += 2; }
                if (d.sourcing >= 8) { valueDelta += 2; credDelta += 3; } // traceability is verifiable

                // The visible rider scheme adds some value but with diminishing weight.
                valueDelta += Math.min(4, visible * 0.7);

                // Photogenic community spend creates little real value and reads as PR if it
                // crowds out the material work.
                valueDelta += Math.min(1.5, photogenic * 0.3);
                spinDelta += Math.min(8, photogenic * 0.7);

                // Thin-spread penalty: if no single material lever is properly funded, the named
                // risk is untouched (Facilitator: "eight feel-good programmes... effluent untouched").
                const concentratedMaterial = (d.water >= 8 || d.sourcing >= 8);
                if (!concentratedMaterial && photogenic >= material) {
                    valueDelta -= 9; credDelta -= 4; coachKey = `coach_r2_thin`;
                } else if (!concentratedMaterial) {
                    valueDelta -= 4; coachKey = `coach_r2_spread`;
                }

                // The governing discipline.
                switch (d.focus) {
                    case `materialroi`:
                        valueDelta += 5; credDelta += 2;
                        if (concentratedMaterial) coachKey = `coach_r2_materialroi`;
                        break;
                    case `spread`:
                        valueDelta -= 4; spinDelta += 3;
                        if (coachKey === `coach_default`) coachKey = `coach_r2_spread`;
                        break;
                    case `cheapest`:
                        valueDelta -= 7; spinDelta += 8;
                        coachKey = `coach_r2_cheapest`;
                        break;
                }

                // Under-spend on the crisis is its own signal (you had R$28M and used a fraction).
                if (spend < 12) { valueDelta -= 5; coachKey = `coach_r2_underspend`; }

                summaryKey = (concentratedMaterial && d.focus === `materialroi`) ? `sum_r2_good`
                    : (photogenic >= material ? `sum_r2_thin` : `sum_r2_weak`);
            } else if (round === 3) {
                // Reporting & disclosure scope (Common Errors 3 & 4 — substance needs assurance;
                // selective disclosure is itself greenwashing).
                // Framework.
                if (d.framework === `gri`) { spend += 1.5; credDelta += 8; }
                else { spinDelta += 6; credDelta -= 4; coachKey = `coach_r3_brochure`; }

                // Assurance level — the antidote to the credibility gap. Reasonable assurance is
                // strongest but its extra R$3.5M cost can tip a maxed-out portfolio over the cap.
                switch (d.assurance) {
                    case `reasonable`: spend += 3.5; credDelta += 15; break;
                    case `limited`:    spend += 2.0; credDelta += 12; break;
                    case `none`:       credDelta -= 6; spinDelta += 6; coachKey = `coach_r3_noassurance`; break;
                }

                // Boundary — own-ops-only hides the supply chain where the issues live.
                if (d.boundary === `supplychain`) {
                    credDelta += 7; valueDelta += 3;
                    if (d.framework === `gri` && d.assurance !== `none`) coachKey = `coach_r3_credible`;
                } else {
                    credDelta -= 7; spinDelta += 6; coachKey = `coach_r3_boundary`;
                }

                // Disclosing the unflattering numbers (incl. the unverifiable effluent data).
                if (d.disclose >= 70) { credDelta += 5; valueDelta += 2; }
                else if (d.disclose <= 30) { credDelta -= 7; spinDelta += 5; if (coachKey === `coach_default`) coachKey = `coach_r3_selective`; }

                summaryKey = (d.framework === `gri` && d.assurance !== `none` && d.boundary === `supplychain`) ? `sum_r3_good`
                    : (d.assurance === `none` || d.boundary === `ownops` ? `sum_r3_spin` : `sum_r3_weak`);
            } else if (round === 4) {
                // Recover, communicate & defend (Common Error 5 — overclaiming re-triggers backlash).
                switch (d.claim) {
                    case `calibrated`: valueDelta += 3; credDelta += 6; trustDirect += 4; coachKey = `coach_r4_calibrated`; break;
                    case `confident`:  spinDelta += 6; trustDirect += 2; coachKey = `coach_r4_confident`; break;
                    case `overclaim`:  spinDelta += 16; valueDelta -= 4; coachKey = `coach_r4_overclaim`; break;
                }

                // Coherence — does the plan integrate priority, funding and reporting?
                switch (d.coherence) {
                    case `integrated`: valueDelta += 5; credDelta += 5; break;
                    case `partial`:    valueDelta += 1; break;
                    case `pr`:         spinDelta += 8; credDelta -= 4; coachKey = `coach_r4_pr`; break;
                }

                // Handling the day-60 NGO follow-up.
                switch (d.followup) {
                    case `engage`:  credDelta += 6; valueDelta += 3; if (d.claim === `calibrated`) coachKey = `coach_r4_engage`; break;
                    case `monitor`: trustDirect -= 1; break;
                    case `defend`:  spinDelta += 8; credDelta -= 4; coachKey = `coach_r4_defend`; break;
                }

                // Restraint — keeping claims inside what is verifiable.
                if (d.restraint >= 70) { credDelta += 3; }
                else if (d.restraint <= 30) { spinDelta += 6; }

                summaryKey = (d.claim === `calibrated` && d.coherence === `integrated` && d.followup === `engage`) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // ---- Resource accounting ----
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 10) / 10;

            // Budget cap BINDS across rounds. R2 input is capped at R$28M, but the R3 reporting
            // spend (up to R$3.5M) sits on top, so a maxed-out portfolio plus reasonable assurance
            // tips over R$28M. Going over means the CFO cuts the plan arbitrarily and you lose
            // control of which priorities survive — modelled as a penalty to value & credibility
            // that scales with the overage (Facilitator: the R$52M-on-R$28M error).
            const overage = Math.max(0, ds.budgetUsed - this.BUDGET_CAP);
            if (overage > 0.001) {
                valueDelta -= Math.min(14, overage * 2.5);
                credDelta -= Math.min(8, overage * 1.5);
                if (coachKey === `coach_default` || coachKey === `coach_r3_credible`) coachKey = `coach_overbudget`;
            }

            // ---- Stakeholder value & reporting credibility move on their deltas ----
            ds.value = Math.max(0, Math.min(100, ds.value + valueDelta));
            ds.credibility = Math.max(0, Math.min(100, ds.credibility + credDelta));

            // ---- Brand trust is driven by REAL value + CREDIBLE disclosure, plus any direct
            // effects, MINUS spin. Spin (PR/overclaim/unverified comms) gives a small short-term
            // bump but is then discounted: claims that outrun verifiable performance invite
            // backlash, so net spin erodes trust over the crisis. ----
            const substanceGain = Math.max(0, valueDelta) * 0.22 + Math.max(0, credDelta) * 0.20;
            const spinBacklash = spinDelta * 0.45;   // net negative pull on trust
            let trustDelta = substanceGain + trustDirect - spinBacklash + Math.min(0, valueDelta) * 0.22;
            ds.trust = Math.max(0, Math.min(100, ds.trust + trustDelta));

            // Greenwashing flag: heavy spin while real value/credibility lag.
            if (spinDelta >= 10 && (ds.value < 45 || ds.credibility < 40)) ds.greenwashFlag = true;

            // Retail delisting risk: by the day-45 review, low credibility means the retailers
            // cannot accept the plan as "verified".
            if (round >= 3 && ds.credibility < 35) ds.delisted = true;
            if (ds.credibility >= 50) ds.delisted = false;

            ds.valueHistory.push(Math.round(ds.value));
            ds.trustHistory.push(Math.round(ds.trust));
            ds.credibilityHistory.push(Math.round(ds.credibility));
            ds.performance = { overallScore: this._composite(ds) };

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                value: Math.round(ds.value),
                valueDelta: Math.round(valueDelta),
                trust: Math.round(ds.trust),
                trustDelta: Math.round(trustDelta),
                credibility: Math.round(ds.credibility),
                credibilityDelta: Math.round(credDelta),
                budgetUsed: ds.budgetUsed,
                greenwashFlag: ds.greenwashFlag,
                delisted: ds.delisted,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`valueDisplay`, `domainState.value`, (v) => Math.round(v));
            uiManager.bind(`trustDisplay`, `domainState.trust`, (v) => {
                const card = document.querySelector(`.consciouscap-card-trust`);
                if (card) {
                    card.classList.toggle(`consciouscap-trust-recovered`, Number(v) >= this.TARGET_TRUST);
                    card.classList.toggle(`consciouscap-trust-crisis`, Number(v) < this.START_TRUST);
                }
                return Math.round(v);
            });
            uiManager.bind(`credibilityDisplay`, `domainState.credibility`, (v) => Math.round(v));
            uiManager.bind(`budgetCardDisplay`, `domainState.budgetUsed`, (v) => {
                const card = document.querySelector(`.consciouscap-card-budget`);
                if (card) card.classList.toggle(`consciouscap-budget-over`, Number(v) > this.BUDGET_CAP + 0.001);
                return `R$` + this._fmtM(Number(v));
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => `R$` + this._fmtM(Number(v)) + `M / R$28M`);

            const self = this;

            // Alignment slider readout.
            const al = document.getElementById(`alignmentInput`);
            const alReadout = document.getElementById(`alignmentReadout`);
            if (al && alReadout) {
                alReadout.textContent = al.value;
                al.addEventListener(`input`, function() { alReadout.textContent = al.value; });
            }

            // Disclose slider readout.
            const di = document.getElementById(`discloseInput`);
            const diReadout = document.getElementById(`discloseReadout`);
            if (di && diReadout) {
                diReadout.textContent = di.value;
                di.addEventListener(`input`, function() { diReadout.textContent = di.value; });
            }

            // Live allocation total against the R$28M cap.
            const allocIds = [`waterInput`, `sourcingInput`, `ridersInput`, `communityInput`];
            const allocReadout = document.getElementById(`allocReadout`);
            const recompute = function() {
                let total = 0;
                allocIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseFloat(el.value) || 0);
                });
                total = Math.round(total * 10) / 10;
                if (allocReadout) allocReadout.textContent = `R$` + self._fmtM(total) + `M`;
                const bar = document.querySelector(`.consciouscap-alloc-readout`);
                if (bar) bar.style.color = (total > self.BUDGET_CAP + 0.001) ? `#c0392b` : ``;
            };
            allocIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _fmtM(v) {
            // R$ millions: integers shown plainly, fractions to one decimal with a comma (pt-BR).
            const rounded = Math.round(v * 10) / 10;
            if (Math.abs(rounded - Math.round(rounded)) < 0.001) return String(Math.round(rounded));
            return rounded.toFixed(1).replace(`.`, `,`);
        }

        _composite(ds) {
            const value = Math.round(ds.value);
            const trust = Math.round(ds.trust);
            const credibility = Math.round(ds.credibility);
            return Math.max(0, Math.min(100, Math.round(value * 0.40 + Math.min(100, (trust - 40) * (100 / 60)) * 0.30 + credibility * 0.30)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getChartConfig() {
            return {
                consciousChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_value`, `Stakeholder Value`),
                                data: [],
