                                backgroundColor: `rgba(47,125,69,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2f7d45`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_trust`, `Brand Trust`),
                                data: [],
                                borderColor: `#2a7da3`,
                                backgroundColor: `rgba(42,125,163,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2a7da3`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_cred`, `Reporting Credibility`),
                                data: [],
                                borderColor: `#7a4fb0`,
