                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#6a7d5e` }, grid: { color: `rgba(31,81,48,0.08)` },
                                title: { display: true, text: this._cl(`axis_score`, `0–100`), color: `#6a7d5e` }
                            },
                            x: {
                                ticks: { color: `#6a7d5e` }, grid: { color: `rgba(31,81,48,0.06)` },
