        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.valueHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                consciousChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.valueHistory },
                        { data: ds.trustHistory },
                        { data: ds.credibilityHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const value = Math.round(ds.value);
            const trust = Math.round(ds.trust);
            const credibility = Math.round(ds.credibility);

            const recovered = trust >= this.TARGET_TRUST;
            const substantive = value >= 60 && credibility >= 60;
            const greenwash = ds.greenwashFlag || (trust >= this.START_TRUST && credibility < 40);
            const composite = this._composite(ds);

            let performanceKey = `grade_crisis`;
            if (recovered && substantive && composite >= 72) performanceKey = `grade_conscious`;
            else if (recovered && substantive) performanceKey = `grade_recovery`;
            else if (greenwash) performanceKey = `grade_greenwash`;
            else if (ds.delisted) performanceKey = `grade_delisted`;
            else if (trust > this.START_TRUST) performanceKey = `grade_calmer`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (recovered && substantive) insights.push(window.mySimulation.t(`insight_conscious`));
            else if (greenwash) insights.push(window.mySimulation.t(`insight_greenwash`));
            else if (ds.delisted) insights.push(window.mySimulation.t(`insight_delisted`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (value < 45) insights.push(window.mySimulation.t(`insight_lowvalue`));
            if (credibility < 45) insights.push(window.mySimulation.t(`insight_lowcred`));
            if (ds.budgetUsed > this.BUDGET_CAP) insights.push(window.mySimulation.t(`insight_overbudget`));
            if (recovered && substantive && credibility >= 70) insights.push(window.mySimulation.t(`insight_verified`));

            return {
                value: value,
                trust: trust,
                credibility: credibility,
                recovered: recovered,
                greenwash: greenwash,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                sound: (recovered && substantive),
                greenwashFlag: ds.greenwashFlag,
                delisted: ds.delisted,
                budgetUsed: ds.budgetUsed,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="consciouscap-cm-badge consciouscap-cm-yes">` + T(`cm_credible`) + `</span>`
                : `<span class="consciouscap-cm-badge consciouscap-cm-no">` + T(`cm_notcredible`) + `</span>`;
            let failBadges = ``;
            if (s.greenwashFlag) failBadges += ` <span class="consciouscap-cm-badge consciouscap-cm-fail">` + T(`cm_greenwash`) + `</span>`;
            if (s.delisted) failBadges += ` <span class="consciouscap-cm-badge consciouscap-cm-fail">` + T(`cm_delisted`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="consciouscap-cm-metric"><span class="consciouscap-cm-mv">` + Math.round(s.value || 0) + `</span><span class="consciouscap-cm-ml">` + T(`cm_m_value`) + `</span></div>`
                + `<div class="consciouscap-cm-metric"><span class="consciouscap-cm-mv">` + Math.round(s.trust || 0) + `</span><span class="consciouscap-cm-ml">` + T(`cm_m_trust`) + `</span></div>`
                + `<div class="consciouscap-cm-metric"><span class="consciouscap-cm-mv">` + Math.round(s.credibility || 0) + `</span><span class="consciouscap-cm-ml">` + T(`cm_m_cred`) + `</span></div>`
                + `<div class="consciouscap-cm-metric"><span class="consciouscap-cm-mv">R$` + (Math.round(Number(s.budgetUsed || 0) * 10) / 10) + `M</span><span class="consciouscap-cm-ml">` + T(`cm_m_budget`) + `</span></div>`;
            return ``
                + `<div class="consciouscap-completion">`
                +   `<div class="consciouscap-cm-head">`
                +     `<div class="consciouscap-cm-score">` + score + `<span class="consciouscap-cm-score-max">/100</span></div>`
                +     `<div class="consciouscap-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="consciouscap-cm-metrics">` + metrics + `</div>`
                +   `<div class="consciouscap-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="consciouscap-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.greenwashFlag) return window.mySimulation.t(`hint_greenwash`);
            if (ds.credibility < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_cred`);
            if (ds.value < 35) return window.mySimulation.t(`hint_value`);
            if (ds.budgetUsed > this.BUDGET_CAP) return window.mySimulation.t(`hint_budget`);
            if (ds.trust >= this.TARGET_TRUST && ds.value >= 60 && ds.credibility >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.value`, label: `Value`, i18nKey: `col_value`, formatter: (v) => Math.round(v) },
                { key: `results.trust`, label: `Trust`, i18nKey: `col_trust`, formatter: (v) => Math.round(v) },
                { key: `results.credibility`, label: `Credibility`, i18nKey: `col_cred`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

